import{_ as e,A as a,q as t,B as i,aV as o,H as n}from"./chunks/framework.B_e8lQlv.js";const r=JSON.parse('{"title":"为什么选择我们?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction/why.md","filePath":"guide/introduction/why.md"}');const d=e({name:"guide/introduction/why.md"},[["render",function(e,r,d,l,s,c){const h=a("NolebaseGitContributors"),u=a("NolebaseGitChangelog");return t(),i("div",null,[r[0]||(r[0]=o('<h1 id="为什么选择我们" tabindex="-1">为什么选择我们? <a class="header-anchor" href="#为什么选择我们" aria-label="Permalink to &quot;为什么选择我们?&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">写在前面</p><p>我们不会去和其他框架做比较。我们认为每个框架都有自己的特点，适合不同的场景。我们的目标是提供一个简单、易用的框架，让开发者可以快速上手，专注于业务逻辑的开发。所以我们只会不断完善和优化我们的框架，提供更好的体验。</p></div><p>我们致力于为开发者提供一个高效、现代、易用的前端框架。我们的解决方案基于最新的技术栈，如 Vue3、Vite 和 TypeScript，确保您在构建项目时始终走在技术的前沿。同时，我们注重代码的质量与规范，通过严格的工具链保证代码的一致性和可维护性。无论是初创项目还是企业级应用，我们的框架都能帮助您快速构建、迭代和部署。</p><h2 id="框架历程" tabindex="-1">框架历程 <a class="header-anchor" href="#框架历程" aria-label="Permalink to &quot;框架历程&quot;">​</a></h2><p>从 Vue Vben Admin 1.x 版本开始，框架经历了许多迭代和优化。从一开始使用 <code>Vite 0.x</code> 版本，没有现成的插件，开发了很多自定义插件来弥合 Webpack 和 Vite 之间的差异。虽然很多现在已经被代替，但是我们的初衷一直没有变，就是提供一个简单、易用的框架。</p><p>虽然中间有段时间由社区维护，但我们一直密切关注 Vue Vben Admin 的发展。见证了许多开发者使用 Vben Admin，并提供了许多宝贵的建议和反馈。非常感谢大家的支持和贡献，这些都是我们持续改进 Vben Admin 的动力。新版本中，我们持续收集用户反馈，重新开始，不断优化框架，以提供更好的用户体验。我们的目标是让开发者能够快速上手，专注于业务逻辑的开发。</p><h2 id="单元测试" tabindex="-1">单元测试 <a class="header-anchor" href="#单元测试" aria-label="Permalink to &quot;单元测试&quot;">​</a></h2><p>单元测试是确保代码质量的基石。在开发过程中编写和执行单元测试，以捕捉潜在的错误并提升代码的可靠性。框架核心逻辑使用 <code>vitest</code> 做了单元测试，并在逐步增加覆盖率。通过单元测试，可以放心地进行代码重构，减少回归问题，从而提高整体开发效率。</p><h2 id="质量与规范" tabindex="-1">质量与规范 <a class="header-anchor" href="#质量与规范" aria-label="Permalink to &quot;质量与规范&quot;">​</a></h2><p>我们始终高度重视代码的质量与规范。通过使用 Oxfmt、Oxlint、ESLint、Stylelint、Publint、CSpell 等工具来确保代码质量。我们的代码规范基于 Vue3、Vite、TypeScript 等现代前端技术制定，旨在提供一个简洁、易用的框架，使开发者能够快速上手并专注于业务逻辑的开发。</p>',10)),n(h),n(u)])}]]);export{r as __pageData,d as default};
